-- VTI programme catalogue update (NOT APPLIED).
--
-- Mirrors src/platform/content/fixtures/data.ts for the two source-backed VTI
-- programmes (see docs/content/vti-programmes-source-matrix.md). Production
-- currently renders the fixtures (CONTENT_SOURCE), so applying this changes
-- nothing on the public sites until the content source is switched to
-- Supabase. Apply only after the client approves the wording.
--
-- Non-destructive: nothing is deleted. Existing rows, and any applications
-- that reference them, stay intact. The retired demo VTI rows are only
-- unpublished (is_public = false). The two new rows are inserted as drafts:
-- publish them through the admin workflow once approved.

begin;

-- 1. Unpublish the demo VTI programmes (kept for historical integrity).
update public.programmes
set is_public = false
where site = 'vti'
  and slug in ('plumbing', 'compressed-earth-brick', 'professional-growth-engineering', 'food-processing', 'electrical-works');

-- 2. The two current offerings, as drafts, applications closed.
insert into public.programmes
  (site, world, slug, name, summary, type, status, application_open, body, seo, provenance, status_content, is_public)
values
  ('vti', 'vti', 'local-manufacturing-sustainable-construction', 'Local Manufacturing & Sustainable Construction', 'Practical training across local manufacturing and durable construction: making products, working with equipment, applying quality standards and building. NAMACS is the principal structure for this field.', 'Vocational programme', 'under_development', false,
   '[{"type":"heading","level":2,"text":"Overview"},{"type":"paragraph","text":"Local manufacturing and sustainable construction is one of the two principal fields Nayokan has set out for productive-sector training. It follows the chain from making and equipping to quality and construction, and treats digital technology as part of that chain rather than a separate subject."},{"type":"paragraph","text":"Training is offered through the Nayokan Vocational Training Institute. NAMACS is named in the Nayokan brochure as the principal structure for this field."},{"type":"heading","level":2,"text":"Why it matters"},{"type":"paragraph","text":"Goods made locally and structures built to last are two of the clearest places where skills turn directly into productive enterprise. Nayokan''s approach is to train for the whole chain rather than a single trade, so that capability can grow into work and into enterprise."},{"type":"heading","level":2,"text":"Who it is for"},{"type":"paragraph","text":"The field is intended for young people and women looking for practical skills for productive work, in line with Nayokan''s mission of economic transformation for youth and women. Entry requirements have not yet been published."},{"type":"heading","level":2,"text":"What participants learn"},{"type":"paragraph","text":"The curriculum is still being developed. The areas below describe the field, not a finished timetable."},{"type":"list","items":["Manufacturing: producing goods locally.","Equipment: working with the equipment that production depends on.","Quality: checking that products and work meet a consistent standard.","Construction: building with a focus on durability.","Digital technology: applied across each stage of the chain."]},{"type":"heading","level":2,"text":"From training to enterprise"},{"type":"paragraph","text":"Nayokan''s ecosystem runs from competence and innovation through incubation and financing to employment and enterprise growth. Training in this field sits at the start of that route. Where a participant''s work grows into an enterprise, the Nayokan Startup Centre is the route for incubation."},{"type":"heading","level":2,"text":"Programme details"},{"type":"callout","text":"Duration, schedule, fees, entry requirements and certification will be published once Nayokan confirms them. Register your interest and the VTI team will be in touch."}]'::jsonb, '{"title":"Local Manufacturing & Sustainable Construction","description":"A Nayokan VTI training field covering local manufacturing, equipment, quality and durable construction, with digital technology across the chain."}'::jsonb, '{"isDemo": false}'::jsonb, 'draft', false)
on conflict (site, slug, locale) do update set
  name = excluded.name, summary = excluded.summary, type = excluded.type, status = excluded.status,
  application_open = false, body = excluded.body, seo = excluded.seo, provenance = excluded.provenance;

insert into public.programmes
  (site, world, slug, name, summary, type, status, application_open, body, seo, provenance, status_content, is_public)
values
  ('vti', 'vti', 'agro-industrialization-export-systems-market-access', 'Agro-Industrialization, Export Systems & Market Access', 'A professional certificate that links local food processing to the systems that move products to market: packaging and quality, customs and transit, transport and logistics. Being developed by Nayokan Association with Gloway.', 'Professional certificate', 'under_development', false,
   '[{"type":"heading","level":2,"text":"Overview"},{"type":"paragraph","text":"Transform locally. Move efficiently. Trade competitively."},{"type":"paragraph","text":"Processing without a market is not industrialization. This professional certificate prepares food processors, trade operators and small businesses to transform products locally, move them efficiently and trade competitively, by connecting food processing to the standards, logistics and buyer requirements that decide whether a product reaches a market."},{"type":"paragraph","text":"It is being developed by Nayokan Association with Gloway, Nayokan''s principal partner for agrobusiness and agro-food. It sits within the policy context of Cameroon''s SND30, import substitution and agro-industrialization."},{"type":"heading","level":2,"text":"Why it matters"},{"type":"paragraph","text":"Cameroon needs more than local transformation. It needs transformed products that can move through standards, logistics and buyers. A processor can transform well and still fail if the product is not packaged, compliant, costed, documented and connected to buyers."},{"type":"paragraph","text":"The programme starts from market requirements and works backwards. Production is built for a market from the beginning, instead of searching for a buyer after the stock is made."},{"type":"heading","level":2,"text":"Who it is for"},{"type":"paragraph","text":"Food processors, trade operators and small and medium enterprises. Each module is tied to a job function, an enterprise need or a trade operation."},{"type":"heading","level":2,"text":"What participants learn"},{"type":"list","items":["Food processing: hygiene, preservation, standardization and value addition.","Packaging and quality: food-grade packaging, labelling, traceability and product consistency.","Customs and transit: trade documents, customs workflow and clearance coordination.","Transport and logistics: warehousing, cold chain, inland transport, freight and containers."]},{"type":"heading","level":2,"text":"Practical activities"},{"type":"paragraph","text":"Real Cameroonian foods become the classroom. Learners work with actual products, such as leafy vegetables like ndolé, beans and dry foods, specialty foods, and prepared or wrapped foods, so that training leads to better processing, packaging, costing and readiness. The aim is local value addition before products enter domestic or export distribution."},{"type":"paragraph","text":"The programme is also designed to introduce learners to real export workflows: receiving, inspecting, consolidating, preparing and loading goods, and sourcing, compliance, costing and shipment visibility, through Gloway''s systems."},{"type":"heading","level":2,"text":"From certificate to market"},{"type":"paragraph","text":"The certificate is the start of a pathway from skills to market participation:"},{"type":"list","ordered":true,"items":["Certify: complete a practical assessment.","Incubate: strengthen the enterprise and the product.","Qualify: meet supplier and product requirements.","List: eligible profiles can be considered for the Gloway supplier network.","Access: requests for quotation and supply opportunities."]},{"type":"callout","tone":"warn","text":"Completing the training does not itself mean regulatory approval, supplier qualification or a guaranteed export contract. Opportunities depend on demand, quality, capacity and reliability."},{"type":"paragraph","text":"Eligible trained processors can also be supported toward export compliance onboarding, including preparation for FDA facility registration where it applies to businesses targeting the U.S. market. This is preparation support, not an approval."},{"type":"heading","level":2,"text":"Programme details"},{"type":"callout","text":"This programme is in development with its partners. Duration, schedule, fees, entry requirements, assessment and the recognition of the certificate will be published once confirmed. Register your interest and the VTI team will be in touch."}]'::jsonb, '{"title":"Agro-Industrialization, Export Systems & Market Access","description":"A professional certificate in development at Nayokan VTI with Gloway: food processing, packaging and quality, customs and transit, and transport and logistics."}'::jsonb, '{"isDemo": false}'::jsonb, 'draft', false)
on conflict (site, slug, locale) do update set
  name = excluded.name, summary = excluded.summary, type = excluded.type, status = excluded.status,
  application_open = false, body = excluded.body, seo = excluded.seo, provenance = excluded.provenance;

commit;
